Item.method_code:
    string action = this.getAction();
    string userId = this.getID();

    if ("add".Equals(action, StringComparison.OrdinalIgnoreCase) &&
        ClientAdminUserId.Equals(userId, StringComparison.OrdinalIgnoreCase))
    {
        this.setProperty("password", GeneratePasswordHash());
    }

    return this;
}

private const string ClientAdminUserId = "53267AB3CDC94F4ABF9B1D401CDB412F";

private static string GeneratePasswordHash()
{
    byte[] bytes = new byte[16];

    using (var rng = System.Security.Cryptography.RandomNumberGenerator.Create())
    {
    	rng.GetBytes(bytes);
    }

    return new Guid(bytes).ToString("N").ToUpperInvariant();
